pointLocator.script:
time_polling_ms = {num_polling_out_comm}*{time_polling_plc_ms};

if(beginTs.time == null){
    return 0;
}else{
    if(Date.now() - beginTs.time > time_polling_ms) 
    {
        return 0;
    }
    else 
    {
        return 1;
    }
}

var etd = [];

for (ndet = 1; ndet <= 8; ndet++) {
    if(typeof this['avgSpeedKph_'+ndet] != 'undefined'){
        var det = new Object();

        det.timestamp = this['beginTs_'+ndet].value;
        det.integration_period = this['durationS_'+ndet].value;
        det.current_direction = true;
        det.n_vehicles = this['vehicleCounter_'+ndet].value;
        det.occupancy = this['occupationPct_'+ndet].value;
        det.congestion = this['congestion_'+ndet].value;
        det.kamikaze = this['oppositeDirectionCounter_'+ndet].value > 0 ? true : false;
        det.average_speed = this['avgSpeedKph_'+ndet].value;
        det.average_length = this['avgLengthMm_'+ndet].value / 1000.0;
        det.gap = this['intervehicleDistanceMm_'+ndet].value / 1000.0;;
        det.headway = this['intervehicleDistanceMm_'+ndet].value / 1000.0;;
        det.fail_data = false;

        det.veh_speed_1 = this['avgSpeedKph_class_0_' + ndet].value;
        det.veh_speed_2 = this['avgSpeedKph_class_1_' + ndet].value;
        det.veh_speed_3 = this['avgSpeedKph_class_2_' + ndet].value;
        det.veh_speed_4 = this['avgSpeedKph_class_3_' + ndet].value;
        det.veh_speed_5 = this['avgSpeedKph_class_4_' + ndet].value;
        det.veh_speed_6 = this['avgSpeedKph_class_5_' + ndet].value;
        det.veh_speed_7 = this['avgSpeedKph_class_6_' + ndet].value;
        det.veh_speed_8 = this['avgSpeedKph_class_7_' + ndet].value;
   det.veh_speed_9 = this['avgSpeedKph_class_8_' + ndet].value;

        det.veh_pa_1 = this['classificationCounter_class_0_' + ndet].value;
        det.veh_pa_2 = this['classificationCounter_class_1_' + ndet].value;
        det.veh_pa_3 = this['classificationCounter_class_2_' + ndet].value;
        det.veh_pa_4 = this['classificationCounter_class_3_' + ndet].value;
        det.veh_pa_5 = this['classificationCounter_class_4_' + ndet].value;
        det.veh_pa_6 = this['classificationCounter_class_5_' + ndet].value;
        det.veh_pa_7 = this['classificationCounter_class_6_' + ndet].value;
        det.veh_pa_8 = this['classificationCounter_class_7_' + ndet].value;
    det.veh_pa_9 = this['classificationCounter_class_8_' + ndet].value;


        etd.push(det);
    }
}

var jsonString = JSON.stringify(etd);
return jsonString;

time_polling_ms = {num_polling_out_comm}*{time_polling_plc_ms};

if(beginTs.time == null){
    return 0;
}else{
    if(Date.now() - beginTs.time > time_polling_ms) 
    {
        return 0;
    }
    else 
    {
        return 1;
    }
}
